assert all(4 <= len(a) <= 6 for _, a in added)
open(path, 'w', encoding='utf-8').write('[' + chr(10) + (',' + chr(10)).join(' ' + json.dumps(x, ensure_ascii=False) for x in cur + added) + chr(10) + ']' + chr(10))  # one prompt per line, as the file has always been
